package in.aicon.pocket;
import android.content.*;import android.database.Cursor;import android.database.sqlite.SQLiteDatabase;import java.util.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=35)
public class LedgerTransferTest {
 SQLiteDatabase local,account;LedgerSyncStore sync;String subject="567890123456789012345";
 @Before public void setup()throws Exception{Context context=RuntimeEnvironment.getApplication();context.deleteDatabase(AccountScope.LOCAL_DATABASE);context.deleteDatabase(AccountScope.databaseFor(subject));local=context.openOrCreateDatabase(AccountScope.LOCAL_DATABASE,0,null);account=context.openOrCreateDatabase(AccountScope.databaseFor(subject),0,null);LedgerSyncStore.schema(local);sync=new LedgerSyncStore(account,subject);new CatalogStore(local).seed(new String[]{"Food"},new String[]{"Cash"});new SettingsStore(local).put("palette","Rose");ContentValues v=new ContentValues();v.put("uuid",UUID.randomUUID().toString());v.put("kind","lent");v.put("amount",10000);v.put("day","2026-11-11");v.put("account","Cash");v.put("dest","");v.put("category","Debt");v.put("note","");v.put("person","Sample");v.put("loan","");String loan=v.getAsString("uuid");local.insertOrThrow("tx",null,v);v.put("uuid",UUID.randomUUID().toString());v.put("kind","repay_in");v.put("amount",2000);v.put("loan",loan);local.insertOrThrow("tx",null,v);}
 @After public void close(){local.close();account.close();}
 long count(SQLiteDatabase db,String table){try(Cursor c=db.rawQuery("SELECT count(*) FROM "+table,null)){c.moveToFirst();return c.getLong(0);}}
 @Test public void explicitCopyKeepsSourceAndLinksAndCapturesNewAccountClock()throws Exception{Map<String,SyncModel.Record> records=LedgerTransfer.localSnapshot(local);account.beginTransaction();try{LedgerTransfer.intoEmptyAccount(account,sync,records);account.setTransactionSuccessful();}finally{account.endTransaction();}assertEquals(2,count(local,"tx"));assertEquals(2,count(account,"tx"));assertEquals("Rose",new SettingsStore(account).get("palette"));assertEquals(records.keySet(),sync.snapshot().records.keySet());for(SyncModel.Record record:sync.snapshot().records.values())assertFalse(record.clock.isEmpty());try(Cursor c=account.rawQuery("SELECT count(*) FROM tx payment JOIN tx loan ON payment.loan=loan.uuid",null)){c.moveToFirst();assertEquals(1,c.getInt(0));}}
 @Test public void repeatCopyAndNonlocalSourceAreRejectedWithoutReplacing()throws Exception{Map<String,SyncModel.Record> records=LedgerTransfer.localSnapshot(local);account.beginTransaction();try{LedgerTransfer.intoEmptyAccount(account,sync,records);account.setTransactionSuccessful();}finally{account.endTransaction();}long revision=sync.snapshot().revision;account.beginTransaction();try{try{LedgerTransfer.intoEmptyAccount(account,sync,records);fail();}catch(IllegalStateException expected){}}finally{account.endTransaction();}assertEquals(revision,sync.snapshot().revision);assertEquals(2,count(account,"tx"));try{LedgerTransfer.localSnapshot(account);fail();}catch(IllegalArgumentException expected){}}
 @Test public void failedCopyTransactionKeepsEmptyTargetAndSource()throws Exception{Map<String,SyncModel.Record> records=LedgerTransfer.localSnapshot(local);account.beginTransaction();try{LedgerTransfer.intoEmptyAccount(account,sync,records);}finally{account.endTransaction();}assertTrue(sync.snapshot().records.isEmpty());assertEquals(0,count(account,"tx"));assertEquals(2,count(local,"tx"));}
}
